#!/usr/bin/env python3
# d313_4b2_parche.py — DAY313, paso 4b.2 de DEBT-ETCD-HA-TLS-RAFT-001 (un solo uso: NO se commitea).
# etcd-server con HTTPS + mTLS y autorización por (OU, CN); tls.modo "http" de transición en el defender; registro y
# latido del etcd-server en proceso (fuera HttpEtcdRegistrar/CryptoEpochCoordinator); servidor miembro (stop() lo para);
# log [ETCD←] con el status real; fuera /seed y /secrets/keys; resumen [CONFIG-DEFAULT] con la ruta real.
# v2 DAY313: corrige el falso -Wstringop-overflow de GCC 12 + LTO en etcd_server_authz.hpp (parse_authz).
# Acepta como partida la rama limpia (7a666174) o el árbol con el parcheador v1 ya aplicado.
# Uso (Mac, raíz del repo, rama feat/etcd-mtls-vault en 7a666174):
#   python3 -I scripts/d313_4b2_parche.py --check    valida todo y no escribe nada
#   python3 -I scripts/d313_4b2_parche.py --apply    valida todo y, solo si todo cuadra, escribe
# Valida ANTES de escribir: sha256 de partida de cada fichero modificado, que los nuevos no existan, y "ya aplicado"
# (todos con el sha256 final -> no hace nada, rc 0). Mezcla de estados -> no escribe nada, rc 1.
# Escribe cada fichero por tmp + rename y comprueba su sha256 final.
import base64, hashlib, os, sys
FICHEROS = [{'ruta': 'etcd-server/CMakeLists.txt', 'ini': '01decd2dfaf132ea0d56c4f56ddde4e9d7e15157ed63bb1da48cbcad79e237f0', 'otros_ini': [], 'fin': '6ffa5329711bd3e6d7ffe60f6616765cb405a7999031a1b8ac58b1599be99ed4', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/config/etcd-server.etcd-vm.json', 'ini': None, 'otros_ini': [], 'fin': '470a3e3acb865ea8e69b879d0fc592bcc8d671021309957d4dbb1ef9e791e4c6', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/config/etcd-server.json', 'ini': 'eb5a3e9a998d150f4ca0fddcf077c58706ee694fbe9ff11ba97073203d7c9280', 'otros_ini': [], 'fin': '19f7f98601d5f632511726dbff145bc7fa72b1ec0e594439ef99615b21458cd0', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/etcd_server.hpp', 'ini': '8442edd4fad1a258809dc302816f97c9fbac90b5afda3d4dcc28e7f590e605d4', 'otros_ini': [], 'fin': '48a6028a670da21d072040609e2c44a3961d809d637e3daca225b6ad6a1ec1ef', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/etcd_server_authz.hpp', 'ini': None, 'otros_ini': ['36a459af8db8a496b7943d941e0b032888dde0fba3e6f20e4646df0b3355c441'], 'fin': 'eb3990425e07df20c892e5f6c87b07c8902da4f18b64b8e760f9812dd091348c', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/include/etcd_server/etcd_server_config.hpp', 'ini': 'e8c8d01a54a16dfc8c125b25389f5933abdb06a9af1b314ec7b6640b0b03dddc', 'otros_ini': [], 'fin': 'fe22bb84bdad4fba46da5c9f9203c1f9af773724661fd6d9cc1f3a774e5ee752', 'modo': '0o644', 'b64': ''}, {'ruta': 'etcd-server/src/etcd_server.cpp', 'ini': '7b9ba102e7619bd1c586661ad327b527e91504e47f700cb7494371e4009f64dd', 'otros_ini': [], 'fin': 'ff776031c10e06838a0d3e0b8a52ee9920fa43fcc363345d0fe692f4e1326f8e', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/src/main.cpp', 'ini': '66660eb9d191e673779efdf711ee02c18869f6c81a2d40bdd1a3ac71e5def2a4', 'otros_ini': [], 'fin': '7b0fdb7fceb56ae405e0e85192344d12eeaaf64005022b6cf9d5da2a981d6506', 'modo': '0o755', 'b64': ''}, {'ruta': 'etcd-server/tests/test_etcd_server_authz.cpp', 'ini': None, 'otros_ini': [], 'fin': '9a719b6e1d2f87cfad307b5bbac89aba79b06f1d3ea9f41c9c399ec81ee1a44b', 'modo': '0o644', 'b64': ''}, {'ruta': 'scripts/etcd_ha/d313_es_medir.sh', 'ini': None, 'otros_ini': [], 'fin': 'df46babaa49b5441bb5988b139eee7223e79b692bcc3dbbf2182558d3a5cca99', 'modo': '0o755', 'b64': ''}, {'ruta': 'scripts/etcd_ha/d313_es_vm.sh', 'ini': None, 'otros_ini': [], 'fin': '73f49ac2b6716b3562da23e7fdf1b944496b6b716388c7a472313cf1308f24ee', 'modo': '0o755', 'b64': ''}]
def sha(p):
    with open(p, 'rb') as f: return hashlib.sha256(f.read()).hexdigest()
def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ('--check', '--apply'):
        print('uso: python3 -I scripts/d313_4b2_parche.py --check|--apply'); return 2
    if not (os.path.isfile('Vagrantfile') and os.path.isdir('.git') and os.path.isdir('etcd-server')):
        print('[D313-PARCHE] FALLA: no estoy en la raíz del repo'); return 1
    aplicados = pendientes = corregir = 0; errores = []
    for e in FICHEROS:
        r = e['ruta']; existe = os.path.exists(r)
        actual = sha(r) if existe else None
        if actual == e['fin']:
            aplicados += 1; estado = 'ya aplicado'
            if e['otros_ini']: corregir += 1
        elif e['ini'] is None and not existe:
            pendientes += 1; estado = 'nuevo, pendiente'
        elif e['ini'] is not None and actual == e['ini']:
            pendientes += 1; estado = 'partida OK, pendiente'
        elif existe and actual in e['otros_ini']:
            pendientes += 1; estado = 'partida = parcheador anterior (sin corrección GCC 12), pendiente'
        else:
            estado = 'NO CUADRA'
            errores.append('%s: sha256 %s, esperado partida %s o final %s' % (
                r, (actual or 'no existe')[:16], (e['ini'] or 'no existe')[:16], e['fin'][:16]))
        print('[D313-PARCHE] %-58s %s' % (r, estado))
    if errores:
        for x in errores: print('[D313-PARCHE] FALLA: ' + x)
        print('[D313-PARCHE] no se escribe nada'); return 1
    if pendientes == 0:
        print('[D313-PARCHE] RESULTADO: ya aplicado (%d/%d), no se hace nada' % (aplicados, len(FICHEROS))); return 0
    previos = sum(1 for e in FICHEROS if os.path.exists(e['ruta']) and sha(e['ruta']) in e['otros_ini'])
    if aplicados and not (previos == pendientes and aplicados + previos == len(FICHEROS)):
        print('[D313-PARCHE] FALLA: mezcla de estados (%d aplicados, %d pendientes): no se escribe nada' % (aplicados, pendientes)); return 1
    if sys.argv[1] == '--check':
        print('[D313-PARCHE] RESULTADO --check: %d ficheros listos para aplicar (%d ya en su estado final); nada escrito' % (pendientes, aplicados)); return 0
    for e in FICHEROS:
        r = e['ruta']; d = os.path.dirname(r)
        if os.path.exists(r) and sha(r) == e['fin']: continue
        if d: os.makedirs(d, exist_ok=True)
        datos = base64.b64decode(e['b64'])
        tmp = r + '.d313tmp'
        with open(tmp, 'wb') as f: f.write(datos)
        os.chmod(tmp, int(e['modo'], 8)); os.replace(tmp, r)
        if sha(r) != e['fin']:
            print('[D313-PARCHE] FALLA: %s escrito pero su sha256 no es el final' % r); return 1
    print('[D313-PARCHE] RESULTADO --apply: %d ficheros escritos, sha256 final OK en los %d' % (pendientes, len(FICHEROS))); return 0
sys.exit(main())
